insert into public.platform_topics (id, element_id, group_id, slug, title, description, intro, icon, image_path, image_position, youtube_url, sort_order, published) values ($md$0c326e88-fc6a-4573-863d-f69429d38f9e$md$, $md$f155069b-a824-4cb5-bcc8-0eb4ea595290$md$, $md$afa3d576-1ad0-4986-82c5-7420a2d33e0f$md$, $md$operating-model$md$, $md$Operating Model$md$, $md$How a House is structured, decides, and reports.$md$, $md$This explains how a Palestine House is run: who does what, how decisions are made, and how your House works with HQ. Use it to set up your House the right way from day one.$md$, $md$network$md$, $md$/assets/workspace/topics/operating-model.jpg$md$, $md$50% 53%$md$, NULL, 2, true) on conflict (id) do nothing;
insert into public.platform_topics (id, element_id, group_id, slug, title, description, intro, icon, image_path, image_position, youtube_url, sort_order, published) values ($md$7f8b29b0-32c0-456a-95b4-e4f35b8ea447$md$, $md$aed1028e-4542-4f7b-ad38-3a0116f28c75$md$, $md$afa3d576-1ad0-4986-82c5-7420a2d33e0f$md$, $md$mission-values-and-guest-promise$md$, $md$Mission, Values and Guest Promise$md$, $md$The charter every House runs on — and how to live it daily.$md$, $md$This tells you what Palestine House stands for and the promise every guest must feel when they walk in. Use it to make sure your whole team understands the mission and lives it every day.$md$, $md$heart$md$, $md$/assets/workspace/topics/mission-values-and-guest-promise.jpg$md$, $md$50% 52%$md$, NULL, 3, true) on conflict (id) do nothing;
insert into public.platform_topics (id, element_id, group_id, slug, title, description, intro, icon, image_path, image_position, youtube_url, sort_order, published) values ($md$03320cb1-b40b-4316-811f-b7b121402d6d$md$, $md$6807ec45-bd57-4d88-ae1a-c8ca3924fce7$md$, $md$afa3d576-1ad0-4986-82c5-7420a2d33e0f$md$, $md$brand-experience-standards$md$, $md$Brand Experience Standards$md$, $md$What the brand looks, sounds, and feels like — and HQ approvals.$md$, $md$This shows you exactly how the Palestine House brand must look and feel in your House — from signage to events. Use it to keep everything on-brand and to know when to ask HQ for approval.$md$, $md$sparkles$md$, $md$/assets/workspace/topics/brand-experience-standards.jpg$md$, $md$50% 54%$md$, NULL, 4, true) on conflict (id) do nothing;
